package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var tierLimits [4]decimal.Decimal
var tierRates [4]decimal.Decimal

var salesFile *os.File
var salesReader *bufio.Reader
var salesRec SalesRec

func formatEdited(pic string, d decimal.Decimal) string {
	// Determine integer digits, scale, and comma positions from pic
	// pic like ZZZ,ZZ9.99 etc.
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	scale := len(fracPic)

	// Round/truncate already done before MOVE; here we just format.
	// Ensure decimal has correct scale handling: we need integer part and fractional part.
	// d is positive in this program (sales/commission). Handle negative generically.
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	// Shift to get integer representation at given scale, truncated (already rounded).
	// Use StringFixed to get exact digits.
	s := d.StringFixed(int32(scale))

	// Split integer and fractional
	var intPartStr, fracPartStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", scale)
		}
	} else {
		intPartStr = s
		// remove possible decimal
		if idx := strings.Index(intPartStr, "."); idx >= 0 {
			intPartStr = intPartStr[:idx]
		}
	}

	// intPic may contain commas; remove them to count positions
	intPicNoComma := strings.ReplaceAll(intPic, ",", "")
	intWidth := len(intPicNoComma)

	// If integer digits exceed width, drop high-order digits
	if len(intPartStr) > intWidth {
		intPartStr = intPartStr[len(intPartStr)-intWidth:]
	}
	// Pad on left with zeros to width
	if len(intPartStr) < intWidth {
		intPartStr = strings.Repeat("0", intWidth-len(intPartStr)) + intPartStr
	}

	// Now intPic includes commas; we need to map intPartStr digits to intPic positions
	// Build formatted integer part same length as intPic
	formattedInt := make([]byte, len(intPic))
	// digit index for intPartStr
	// intPic chars: 'Z', '9', ','
	// digitPos corresponds to each non-comma char
	digitIdx := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == ',' {
			formattedInt[i] = ','
		} else {
			formattedInt[i] = intPartStr[digitIdx]
			digitIdx++
		}
	}

	// Apply Z suppression: leading zeros where pic is Z become spaces
	// Commas inside suppressed zone also become spaces.
	// Suppression goes until last Z? Actually Z means suppress if zero and no non-zero has appeared yet.
	// We track whether a non-suppressed digit has been encountered.
	suppressing := true
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == ',' {
			continue
		}
		if c == 'Z' {
			if suppressing && formattedInt[i] == '0' {
				formattedInt[i] = ' '
			} else {
				suppressing = false
			}
		} else if c == '9' {
			// 9 always prints digit; suppression ends
			suppressing = false
		}
	}
	// Now fix commas: any comma that has only spaces to its left (i.e., all non-comma chars left are spaces) becomes space
	// Equivalent to commas inside suppressed zone become spaces. Implement by scanning left to right.
	seenDigit := false
	for i := 0; i < len(formattedInt); i++ {
		if formattedInt[i] == ',' {
			if !seenDigit {
				formattedInt[i] = ' '
			}
		} else if formattedInt[i] != ' ' {
			seenDigit = true
		}
	}

	result := string(formattedInt)
	if scale > 0 {
		// ensure fracPartStr length scale
		if len(fracPartStr) < scale {
			fracPartStr = fracPartStr + strings.Repeat("0", scale-len(fracPartStr))
		} else if len(fracPartStr) > scale {
			fracPartStr = fracPartStr[:scale]
		}
		result = result + "." + fracPartStr
	}
	if neg {
		// For edited pics, sign handling not needed for this program
		result = "-" + result
	}
	return result
}

func moveToEdited(pic string, d decimal.Decimal) string {
	return formatEdited(pic, d)
}

func initPara() {
	tierLimits[0] = decimal.NewFromFloat(1000.00)
	tierLimits[1] = decimal.NewFromFloat(5000.00)
	tierLimits[2] = decimal.NewFromFloat(20000.00)
	tierLimits[3] = decimal.NewFromFloat(999999.99)
	tierRates[0] = decimal.NewFromFloat(2.50)
	tierRates[1] = decimal.NewFromFloat(4.00)
	tierRates[2] = decimal.NewFromFloat(5.50)
	tierRates[3] = decimal.NewFromFloat(7.25)
}

func readPara() {
	line, err := salesReader.ReadString('\n')
	if err != nil {
		// EOF or error: check if we got a line
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		// Last line without newline
	}
	// Remove trailing \n and \r
	line = strings.TrimRight(line, "\r\n")
	// Pad with spaces to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	}
	if len(line) > 12 {
		line = line[:12]
	}
	srId := line[0:4]
	srSalesRaw := line[4:12]
	// digits only
	srSalesRaw = strings.TrimSpace(srSalesRaw)
	// But per spec, field is 8 digits, may be spaces? Treat empty as 0
	if srSalesRaw == "" {
		srSalesRaw = "0"
	}
	n, _ := decimal.NewFromString(srSalesRaw)
	// implied 2 decimal
	srSales := decimal.New(n.IntPart(), -2)
	salesRec.SrId = srId
	salesRec.SrSales = srSales
	// ensure EOF flag not set
	// If we read successfully, keep N (unless EOF next time)
}

func processPara() {
	WsTier = 0
	WsIdx = 1
	for !(WsIdx > 4 || WsTier > 0) {
		if salesRec.SrSales.Cmp(tierLimits[WsIdx-1]) <= 0 {
			WsTier = WsIdx
		}
		WsIdx++
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE /100
	rate := tierRates[WsTier-1]
	val := salesRec.SrSales.Mul(rate).Shift(-2)
	WsComm = val.Round(2)
	// Truncate/store to PIC 9(6)V99 would truncate to 2 decimals already, but Round already 2
	WsTotal = WsTotal.Add(WsComm)
	WsCount++
	WsSalesEd = moveToEdited("ZZZ,ZZ9.99", salesRec.SrSales)
	WsRateEd = moveToEdited("9.99", rate)
	WsCommEd = moveToEdited("ZZZ,ZZ9.99", WsComm)
	fmt.Printf("%s T%d %s %s%% %s\n", salesRec.SrId, WsTier, WsSalesEd, WsRateEd, WsCommEd)
	readPara()
}

func summaryPara() {
	WsTotalEd = moveToEdited("ZZZ,ZZZ,ZZ9.99", WsTotal)
	// WS-COUNT is PIC 9(3) zero padded? But DISPLAY prints it? For unedited numeric, it prints as is with zero padded? However spec says PIC 9(5) prints zero-padded. So PIC 9(3) prints with leading zeros.
	// Need to format WsCount as 3 digits zero-padded
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("REPS: %s TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	initPara()
	var err error
	salesFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer salesFile.Close()
	salesReader = bufio.NewReader(salesFile)
	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	summaryPara()
}
